function kthCharacter(k) {
  let word = 'a';
  while (word.length < k) {
    let shifted = '';
    for (const letter of word) {
      const nextIndex = (letter.charCodeAt(0) - 97 + 1) % 26;
      shifted += String.fromCharCode(97 + nextIndex);
    }
    word += shifted;
  }
  return word[k - 1];
}

brute:
function kthCharacter(k) {
  // Each step copies positions 0..2^j-1 to 2^j..2^(j+1)-1 with one more shift,
  // so 0-based position k - 1 is shifted once for every 1 bit it has.
  let shifts = 0;
  for (let rest = k - 1; rest > 0; rest = Math.floor(rest / 2)) {
    shifts += rest % 2;
  }
  return 'abcdefghijklmnopqrstuvwxyz'[shifts % 26];
}

